fn set_printoptions(
    precision: Option<u8>,
    threshold: Option<u8>,
    edgeitems: Option<u8>,
    linewidth: Option<u8>,
    suppress: Option<bool>,
    nanstr: Option<String>,
    infstr: Option<String>,
    sign: Option<String>,
    floatmode: Option<String>,
    legacy: Option<String>,
) -> () {
    // Validate numeric options: strictly positive u8 if provided.
    if let Some(p) = precision {
        assert!(p > 0, "precision must be strictly positive");
    }
    if let Some(t) = threshold {
        assert!(t > 0, "threshold must be strictly positive");
    }
    if let Some(e) = edgeitems {
        assert!(e > 0, "edgeitems must be strictly positive");
    }
    if let Some(lw) = linewidth {
        assert!(lw > 0, "linewidth must be strictly positive");
    }

    // suppress is a boolean flag; nothing to validate beyond type.
    let _ = suppress;

    // Validate non-empty strings if provided.
    if let Some(s) = nanstr.as_deref() {
        assert!(!s.is_empty(), "nanstr must be non-empty");
    }
    if let Some(s) = infstr.as_deref() {
        assert!(!s.is_empty(), "infstr must be non-empty");
    }

    // Validate sign: "-", "+", or " " (single space).
    if let Some(s) = sign.as_deref() {
        assert!(
            s == "-" || s == "+" || s == " ",
            "sign must be one of \"-\", \"+\", or \" \""
        );
    }

    // Validate floatmode.
    if let Some(s) = floatmode.as_deref() {
        assert!(
            matches!(s, "fixed" | "unique" | "maxprec" | "maxprec_equal"),
            "floatmode must be one of \"fixed\", \"unique\", \"maxprec\", or \"maxprec_equal\""
        );
    }

    // Validate legacy mode.
    if let Some(s) = legacy.as_deref() {
        assert!(
            matches!(s, "1.13" | "1.21" | "1.25" | "2.1" | "2.2"),
            "legacy must be one of \"1.13\", \"1.21\", \"1.25\", \"2.1\", or \"2.2\""
        );
    }

    // No global state is specified in the prompt; this function only validates.
}